/* =====================================================================
   DP = $1D00 throughout (operand $XX -> g_wram[0x1D00+XX]).
   Width/sign notes are explicit: REP #$20 -> 16-bit A; SEP #$20 -> 8-bit A.
   $67/$69 are the HIGH bytes of the 16-bit tentative pos $66/$68 (i.e.
   the tile/cell coordinate); $71/$73 are the high bytes of $70/$72.
   ===================================================================== */

/* ---- C0/9C37: z-plane solidity gate. Returns carry. carry SET = SOLID. ---- */
/* Inputs: $6A = tile z-plane (0..3, from 9AD3 shape-decode), $6C = IGNORE_Z flag
   (byte2&4, 8-bit nonzero), $0155 = current player z-plane. 8-bit A in/out. */
bool zgate_solid(void) {           /* C0/9C37 */
    if (R8($6C) != 0) {            /* 9C37 BNE 9C53: IGNORE_Z tile */
        /* 9C53: only solid if the PLAYER itself is on transition plane 3 */
        if (R8($0155) == 3) return true /*SEC,9C4F*/;   /* 9C56 CMP#3 BEQ 9C4F */
        return false /*CLC,9C5A*/;
    }
    /* 9C3B: normal z compare */
    uint8 z = R8($6A);
    if (z == 0) return true;                   /* 9C3D BEQ 9C4F: z==0 transition-solid */
    if (z == 3) return false;                  /* 9C41 BEQ 9C51: z==3 transition-walkable */
    if (z == R8($0155)) return false;          /* 9C46: same plane as player */
    if (R8($0155) == 3) return false;          /* 9C4D: player on transition plane */
    return true;                               /* 9C4F SEC: the OTHER plane -> SOLID */
}

/* ---- C0/9C5C: per-axis collision COMMIT worker. ---- */
/* On entry the leading-edge probes have already passed; this commits the move
   to the destination cell or blocks it. Returns nothing (caller RTS). */
void collision_commit(void) {      /* C0/9C5C */
    REP_A16();                                  /* 9C5C REP #$20 */
    /* tentative X = base X + X-vel ; stored twice ($66 the probe, $70 a copy) */
    W16($66, R16($62) + R16($2E));              /* 9C5E..9C65 ($62 base pos lo16, $2E X vel) */
    W16($70, R16($66));
    /* tentative Y = base Y + Y-vel */
    W16($68, R16($64) + R16($30));              /* 9C67..9C6C ($64 base Y, $30 Y vel) */
    /* row-wrap neighbour Y: $72 = $68 -/+ 0x100 depending on Y-vel sign.
       (If moving up ($30 bit15 set -> negative) we look one row ABOVE by -0x100,
        else one row below by +0x100.) Used by the door/$7E7000 secondary probe. */
    if (R16($30) & 0x0080) {                    /* 9C6E..9C73 BIT #$0080 on 16-bit A=$30 */
        W16($72, R16($68) - 0x0100);            /* 9C75..9C7B */
    } else {
        W16($72, R16($68) + 0x0100);            /* 9C7F..9C85 */
    }
    /* A:=$68 (16-bit) then SEP; A8:=$67 (HIGH byte of tentative X = cell X) */
    (void)R16($68);                             /* 9C87 LDA $68 (sets up A for 9AC8 below) */
    SEP_A8();                                   /* 9C89 */
    R8($67);                                    /* 9C8B LDA $67 = tentative X cell (A8 arg) */
    propfetch_at_cell();                        /* 9C8D JSR $9AC8: A8=cellX, $68 hi=cellY -> $58/$5A/$5C */
    shape_decode();                             /* 9C90 JSR $9AD3: -> $6A z, $6C ignoreZ, $6E/$6F prio, $5E one-way */
    if (zgate_solid()) {                        /* 9C93 JSR $9C37; 9C96 BCC 9CA1 (clear=continue) */
        REP_A16(); W16($2E,0); W16($30,0);      /* 9C98..9C9C STZ $2E/$30 : BLOCK the move */
        SEP_A8();
        return;                                 /* 9CA0 RTS */
    }
    /* ---- 9CA1: trigger / touch-region lookup ---- */
    trigger_lookup_and_door();                  /* falls through, see below; ends at 9D52 */
    /* ---- 9D54: plane + OBJ-priority update ---- */
    plane_update();                             /* 9D54..9D69 */
    /* ---- 9D6A: one-way scratch + conveyor ---- */
    W8($34, R8($5E));                           /* 9D6A: $34 := $5E (one-way/slope flag scratch) */
    conveyor_apply();                           /* 9D6E..9DBD or 9DBE (writes momentum $2A/$2B) */
}

/* ---- C0/9CA1..9D52: trigger-region lookup + door/$7E7000 secondary check ---- */
void trigger_lookup_and_door(void) {
    if (R8($0117) & 0x80) {                     /* 9CA1: trigger already armed this step */
        goto L_9D2C;                            /* 9CA8 BRL $9D2C: skip the lookup, do door check */
    }
    /* form 16-bit cell index X = (cellY & $1F)<<8 | (cellX & $1E)  (de-interleave into 0x40-strided planes) */
    /* $69 = tentative Y cell ($68 hi); $67 = tentative X cell ($66 hi).
       $1F = Y cell mask, $1E = X cell mask (scene-load: $0F/$1F/$3F per map size). */
    uint8 yi = R8($69) & R8($1F);               /* 9CAB..9CAD */
    uint8 xi = R8($67) & R8($1E);               /* 9CB0..9CB2 */
    REP_X16();                                  /* 9CB4 */
    uint16 X = (yi << 8) | xi;                  /* 9CAF XBA then TAX -> X = yi:xi */
    int16 idx = (int16)R16_long(0x7E7080 + X);  /* 9CB7 LDA $7E7080,X  (16-bit index plane) */
    if (idx < 0) goto L_9D35;                   /* 9CBB BMI $9D35: no trigger here (bit15 sentinel) */
    /* idx * 7 via HW multiply, + $04 (trigger-table row base) -> record offset into $E50000 */
    WMPYA = (uint8)idx; WMPYB = 7;              /* 9CBD..9CC2 (only low byte of idx used as WRMPYA) */
    /* 9CC5-9CC7 NOP x3 = the mandatory 8-cycle multiply wait */
    REP_A16();
    uint16 rec = RDMPY() + R16($04);            /* 9CCA..9CD0: X := RDMPYL + $04 */
    SEP_A8();
    X = rec;
    /* record at $E50000[rec]: [0]=tileX, [1]=tileY, [3]=$0112, [4]=flags(->$0116/$0113), [5]=$0114, [6]=$0115 */
    if (ROM8(0xE50000 + X) == R8($67)) {        /* 9CD3..9CD7: record tileX == tentative cellX ? */
        /* matched on X; require Y within 0x3F of record tileY */
        int8 dy = ROM8(0xE50001 + X) - R8($69); /* 9CE5..9CEA SEC SBC $69 */
        if (dy < 0) dy = -dy;                    /* 9CEC BPL else EOR#FF INC (abs) */
        if ((uint8)dy >= 0x3F) goto L_9D2C;     /* 9CF1 CMP#3F BCS $9D2C: too far -> no trigger */
        goto L_arm;                              /* within range -> arm */
    } else if (ROM8(0xE50001 + X) == R8($69)) { /* 9CDB..9CDF: else record tileY == cellY ? */
        goto L_arm;                              /* 9CE1 BEQ $9CF5 */
    } else {
        goto L_9D2C;                             /* 9CE3 BRA $9D2C: no match -> no trigger */
    }
L_arm: /* 9CF5: populate the trigger fields and set $0117 bit7 (armed) */
    {
        uint8 f = ROM8(0xE50004 + X);            /* 9CF5 -> $52 */
        W8($52, f);
        W8($0116, (f >> 1) & 0x0F);              /* 9CFB..9CFE */
        W8($0116, R8($0116) | (f & 0x80));       /* 9D01..9D05 TSB: OR in bit7 of f */
        W8($0113, f & 0x01);                     /* 9D08..9D0C */
        W8($0112, ROM8(0xE50003 + X));           /* 9D0F..9D13 */
        W8($0114, ROM8(0xE50005 + X));           /* 9D16..9D1A */
        W8($0115, ROM8(0xE50006 + X));           /* 9D1D..9D21 */
        W8($0117, R8($0117) | 0x80);             /* 9D24..9D29: arm the trigger */
    }
L_9D2C: /* door / $7E7000 bit4 secondary check on the ROW-WRAP neighbour cell ($73/$71) */
    {
        /* recompute index for the PRIMARY cell ($69/$67) [9D2C..9D33] -- this value is
           immediately overwritten by the wrap-cell index below, so it is dead unless
           we arrived via the BRL from 9CA8/9CE3 (then it is the live index). */
        uint8 yi2 = R8($69) & R8($1F); uint8 xi2 = R8($67) & R8($1E);
        /* fallthrough re-loads with wrap-neighbour: */
L_9D35:
        uint8 yi3 = R8($73) & R8($1F);           /* 9D35..9D39: wrap-neighbour Y cell */
        uint8 xi3 = R8($71) & R8($1E);           /* 9D3A..9D3C: wrap-neighbour X cell */
        uint16 Xn = (yi3 << 8) | xi3;            /* TAX */
        if (R8_long(0x7E7000 + Xn) & 0x10) {     /* 9D3F..9D45: tile byte1 bit4 = DOOR_TRIGGER */
            W16($015B, Xn);                      /* 9D47 STX $015B: latch the door cell index */
            W8($0117, R8($0117) | 0x10);         /* 9D4A..9D4F: set $0117 bit4 (door pending) */
        }
        SEP_X8();                                /* 9D52 */
    }
}

/* ---- C0/9D54: plane + OBJ-priority update ---- */
void plane_update(void) {           /* C0/9D54 */
    if (R8($6C) == 0) {                          /* 9D54 BNE 9D6A: skip if IGNORE_Z tile */
        W8($0155, R8($6A));                      /* 9D58: player z-plane := tile z-plane */
        uint8 px = R8($0197);                    /* 9D5D LDX $0197 (player actor index) */
        W8(0x0C00 + px, R8($6E));                /* 9D60..9D62: OBJ priority low  := $6E */
        W8(0x0C01 + px, R8($6F));                /* 9D65..9D67: OBJ priority high := $6F */
    }
}

/* ---- C0/9D6E..9DBD: CONVEYOR / forced auto-move ----
   Tile byte1 = $5A. Bits 0x0C select a SPEED; bits 0x03 select a DIRECTION.
   Output: $2A/$2B = the per-frame momentum SEED (signed 8-bit each), which
   C0/88E5 carries into next frame's velocity accumulator. Also sets $34 bit3. */
void conveyor_apply(void) {
    /* (9D6A already did $34 := $5E before this) */
    uint8 sel = R8($5A) & 0x0C;                  /* 9D6E..9D70 */
    if (sel == 0) {                              /* 9D72 BEQ 9DBE: no conveyor */
        W8($2A,0); W8($2B,0);                    /* 9DBE..9DC0: clear momentum */
        return;                                  /* 9DC2 RTS */
    }
    uint8 speed;
    if      (sel == 0x04) speed = 0x08;          /* 9D74/9D82 */
    else if (sel == 0x08) speed = 0x10;          /* 9D78/9D88 */
    else                  speed = 0x20;          /* default (sel==0x0C) 9D7C */
    W8($52, speed);
    W8($34, R8($34) | 0x08);                     /* 9D8C..9D8E TSB #$08: mark "on conveyor" */
    uint8 dir = R8($5A) & 0x03;                  /* 9D90..9D92 */
    switch (dir) {                               /* 9D94 dec/dec dispatch */
      case 0: /* 9DB4 */ W8($2B, (uint8)(0 - speed)); W8($2A,0); return; /* -Y (up)   */
      case 1: /* 9DAD */ W8($2B, speed);              W8($2A,0); return; /* +Y (down) */
      case 2: /* 9DA3 */ W8($2A, (uint8)(0 - speed)); W8($2B,0); return; /* -X (left) */
      case 3: /* 9D9C */ W8($2A, speed);              W8($2B,0); return; /* +X (right)*/
    }
}

/* ---- C0/9DC3: once-per-SCENE-LOAD init (NOT per frame) ----
   Clears trigger/door state and party OBJ priorities, then probes the spawn
   tile to seed the player's z-plane and the 3 party-member OBJ priorities. */
void scene_load_init(void) {        /* C0/9DC3 */
    W8($01AB,0); W8($01AC,0); W8($01AD,0);       /* 9DC3..9DC9 */
    W8_long(0x7F0C00,0); W8_long(0x7F0C80,0);    /* 9DCC..9DD2 */
    W8_long(0x7F0D00,0); W8_long(0x7F0D80,0);    /* 9DD6..9DDA */
    PHD(); D = 0x1D00; /* PLD at end */          /* 9DDE..9DE4: establish DP=$1D00 */
    uint16 cell = R16($0102);                    /* 9DE5 LDA $0102 (spawn cell index, 16-bit) */
    SEP_A8();
    /* A8 = low byte of cell -> 9AC8 prop-fetch (uses $1E mask + $7E70xx planes) */
    propfetch_at_cell_lowbyte(cell);             /* 9DEA JSR $9AC8 */
    W8($66, 0x80);                               /* 9DED..9DEF: probe at sub-cell x=0x80 (centre) */
    W8($68, 0xFF);                               /* 9DF1..9DF3: probe at sub-cell y=0xFF */
    shape_decode();                              /* 9DF5 JSR $9AD3 -> $6A z, $6E/$6F prio */
    uint8 z = R8($6A); if (z == 0) z = 1;        /* 9DF8..9DFC: spawn plane (0 -> default 1) */
    W8($0155, z);                                /* 9DFE */
    uint8 p0 = R8($0197);                        /* 9E03 player actor index */
    W8(0x0C00 + p0, R8($6E)); W8(0x0C01 + p0, R8($6F)); /* 9E01..9E0B: player OBJ prio */
    uint8 p1 = R8($0199);                        /* 9E0E party member 2 */
    W8(0x0C00 + p1, R8($6E)); W8(0x0C01 + p1, R8($6F)); /* 9E11..9E14 */
    uint8 p2 = R8($019B);                        /* 9E17 party member 3 */
    W8(0x0C00 + p2, R8($6E)); W8(0x0C01 + p2, R8($6F)); /* 9E1A..9E1D */
    W8(0x1D34, R8($5E));                         /* 9E20..9E22: $1D34 := one-way scratch */
    PLD();                                       /* 9E25: restore caller D */
    REP_X16();                                   /* 9E26 */
}

/* =====================================================================
   SUPPORT (already-validated, included for input clarity):
   C0/9AC8 prop-fetch: REP X/A; A := (A & $1E)  [mask cellX into 0x40 stride];
       SEP A; X:=A; -> 9AB2.
   C0/9AB2: if ($7E70C0[X] & 0x80) [off-map/solid sentinel] then SEC RTS (solid),
       else $58:=$7E30C0[X] (byte0), $5A:=$7E7000[X] (byte1), $5C:=$7E7040[X]
       (byte2), CLC RTS.
   C0/9AD3 shape-decode: clears $5E/$60/$6A/$6C/$6E; $56:=$68>>2; shape=($58&0xFC)>>2;
       shape 0 -> 9B41 (flat: z=$5C&3, ignoreZ=$5C&4, prio from $5A/$5C); shape 1 ->
       9B62 (alt z packing $5C&0x18>>3); shapes 2..0x15 -> slope test via tables
       C09BF5/C09C0B/C09C21; shapes 0x16..0x1C -> one-way 9B86 (sets $5E one-way /
       forces $30). The OUTPUTS $6A/$6C/$6E/$6F/$5E feed 9C37/9D54/9D6E above.
   ===================================================================== */
